delegate int MyDelegate(int x, int y);

class Program {
    static int Add(int a, int b) {
        return a + b;
    }

    static int Multiply(int a, int b) {
        return a * b;
    }

    static void Execute(MyDelegate del, int a, int b) {
        Console.WriteLine(del(a, b));
    }

    static void Main() {
        MyDelegate d = new MyDelegate(Add);
        Console.WriteLine(d(7, 8));  // 15

        Execute(Multiply, 5, 6);  // 30
    }
}

delegate void Notify(string message);

class Program {
    static void SendEmail(string msg) {
        Console.WriteLine("Email: " + msg);
    }

    static void SendSMS(string msg) {
        Console.WriteLine("SMS: " + msg);
    }

    static void Main() {
        Notify notify = SendEmail;
        notify += SendSMS;

        notify("Hello!");
        // Output:
        // Email: Hello!
        // SMS: Hello!

        notify -= SendEmail;
        notify("Bye!");
        // Output: SMS: Bye!
    }
}

delegate void StateChangedHandler(string oldState, string newState);

class PowerSwitch {
    public event StateChangedHandler StateChanged;
    public string CurrentState { get; private set; }

    public void TurnOn() {
        if (CurrentState != "On") {
            string old = CurrentState;
            CurrentState = "On";
            StateChanged?.Invoke(old, "On");
        }
    }
}

class Program {
    static void Main() {
        PowerSwitch p = new PowerSwitch();
        p.StateChanged += OnStateChanged;
        p.TurnOn();
    }

    static void OnStateChanged(string old, string newState) {
        Console.WriteLine($"State changed from {old} to {newState}");
    }
}

